from pathlib import Path


def replace(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise SystemExit(f"anchor missing in {path}: {old[:80]!r}")
    p.write_text(text.replace(old, new, 1))


def insert_after(path: str, anchor: str, addition: str) -> None:
    replace(path, anchor, anchor + addition)


# Durable semantic agent identity. Root agent identity is deterministic from the
# session identity so session creation can publish both in one transaction.
insert_after(
    "crates/ion-core/src/ids.rs",
    '''impl fmt::Display for SessionId {\n    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\n        write!(f, "session-{}", self.0)\n    }\n}\n''',
    '''\n#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]\npub struct AgentId(Uuid);\n\nimpl AgentId {\n    #[must_use]\n    pub fn generate() -> Self {\n        Self(Uuid::now_v7())\n    }\n\n    /// Deterministic durable identity of one session family's root agent.\n    #[must_use]\n    pub const fn root(session_id: SessionId) -> Self {\n        Self(session_id.as_uuid())\n    }\n\n    #[must_use]\n    pub const fn from_uuid(uuid: Uuid) -> Self {\n        Self(uuid)\n    }\n\n    #[must_use]\n    pub const fn as_uuid(self) -> Uuid {\n        self.0\n    }\n\n    #[must_use]\n    pub fn parse(text: &str) -> Option<Self> {\n        Uuid::parse_str(text).ok().map(Self)\n    }\n}\n\nimpl fmt::Display for AgentId {\n    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {\n        write!(f, "agent-{}", self.0)\n    }\n}\n''',
)

